{% extends "base.html" %}
{% load i18n static %}
{% block title %}SPORTI{% endblock %}
{% block content %}
<div class="min-h-screen w-full relative overflow-hidden bg-[#04060a] text-white">
    <div class="absolute inset-0 bg-cover bg-center opacity-90 lg:hidden"
         style="background-image: url('{% static 'images/design/splash-background.jpg' %}');"></div>
    <div class="absolute inset-0 bg-cover bg-center opacity-90 hidden lg:block"
         style="background-image: url('{% static 'images/design/splash-background-desktop.jpg' %}');"></div>
    <div class="absolute inset-0 bg-gradient-to-b from-black/40 via-black/50 to-black/90"></div>

    <div class="relative z-10 min-h-screen flex flex-col justify-between px-6 py-10">
        <div></div>

        <div class="flex-1 flex flex-col items-center justify-center text-center animate-fade-in-up">
            <div class="relative w-40 h-40 flex items-center justify-center">
                <div class="absolute w-32 h-32 rounded-full bg-cyan-400/25 blur-2xl"></div>
                <img src="{% static 'images/design/sporti-logo-real.png' %}" alt="SPORTI"
                     class="relative w-28 h-28 object-contain">
            </div>
            <h1 id="company-name" class="mt-5 text-2xl font-extrabold tracking-wide">SPORTI</h1>
            <p class="mt-5 text-[15px] font-semibold tracking-wide">
                {% trans "PRÉDISEZ." %} <span class="text-cyan-400">{% trans "GAGNEZ." %}</span> {% trans "DOMINEZ." %}
            </p>
            <p id="company-description" class="mt-2 text-[13px] text-white/65 max-w-xs">
                {% trans "Rejoins la communauté des vrais parieurs intelligents" %}
            </p>
        </div>

        <div class="w-full max-w-sm mx-auto">
            <div class="space-y-3">
                <a href="{% url 'account_signup' %}"
                   class="w-full h-12 rounded-xl bg-[#1f4fff] hover:bg-[#285dff] transition text-white font-semibold flex items-center justify-between px-5 shadow-[0_10px_30px_rgba(31,79,255,0.35)]">
                    <span class="flex items-center gap-2">{% trans "S'INSCRIRE" %}</span>
                    <span>&rsaquo;</span>
                </a>
                <a href="{% url 'account_login' %}"
                   class="w-full h-12 rounded-xl bg-white/5 border border-white/10 hover:bg-white/10 transition text-white font-semibold flex items-center justify-between px-5">
                    <span class="flex items-center gap-2">{% trans "SE CONNECTER" %}</span>
                    <span>&rsaquo;</span>
                </a>
            </div>

            <div class="grid grid-cols-3 gap-3 mt-10 text-center text-white/85">
                <div>
                    <div class="mt-1 text-sm font-semibold">{{ active_members_count }}+</div>
                    <div class="text-[10px] text-white/55">{% trans "Membres actifs" %}</div>
                </div>
                <div>
                    <div class="mt-1 text-sm font-semibold">{{ success_rate }}%</div>
                    <div class="text-[10px] text-white/55">{% trans "Taux de réussite" %}</div>
                </div>
                <div>
                    <div class="mt-1 text-sm font-semibold">{% trans "Quotidien" %}</div>
                    <div class="text-[10px] text-white/55">{% trans "Pronostics" %}</div>
                </div>
            </div>

            <div class="pt-8 pb-1 text-center text-[10px] text-white/45">
                {% trans "Sécurisé. Fiable. 100% Sport." %}
            </div>
        </div>
    </div>
</div>
{% endblock %}
{% block extra_scripts %}
<script>
    fetch("{% url 'company:api_config' %}")
        .then((res) => res.json())
        .then((data) => {
            const profile = data.profile;
            const nameEl = document.getElementById("company-name");
            if (nameEl && profile.name) nameEl.textContent = profile.name;
            const descEl = document.getElementById("company-description");
            if (descEl && profile.description) descEl.textContent = profile.description;
        })
        .catch((err) => console.error("Erreur chargement config entreprise :", err));
</script>
{% endblock %}
SPORTI_EOF
echo "  ecrit: templates/chat/home.html"

echo "Termine. Relance : python manage.py runserver"
